
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_xc_b94_hyb_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_xc_b94_hyb", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.005525923487744e+00, -2.989734278316870e+00, -2.963925971056325e+00, -2.921227835155791e+00, -2.850455839823292e+00, -2.734640373759597e+00, -2.551060303361237e+00, -2.277879391690478e+00, -1.913967469391538e+00, -1.491677884845684e+00, -1.044994966997762e+00, -6.462018374616786e-01, -5.301435592171347e-01, -4.520824152964035e-01, -3.480610894319794e-01, -2.373838463153499e-01, -1.524543026322258e-01, -9.822058006492668e-02, -6.484453459403178e-02, -4.360528596603589e-02]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


